use gpui_dataset_transformation::{glyphs, solid_arrows, tensor_glyphs, GlyphKind};
use gpui_mesh::{DataSet, Field};
use gpui_profiler::AllocProbe;
use std::{hint::black_box, time::Instant};

fn check(output: &DataSet, points: usize, case: &str) {
    output.validate().unwrap();
    let (vertices, triangles) = match case {
        "line_arrows" => (4,3),
        "solid_arrows" => (19,if cfg!(feature="retained") {34} else {24}),
        _ => (26,48),
    };
    assert_eq!(output.point_count(), points*vertices);
    assert_eq!(output.cell_count(), points*triangles);
    if case == "solid_arrows" {
        let mut edges = std::collections::BTreeMap::<(u32,u32), usize>::new();
        for cell in 0..triangles {
            let tri = output.cells.cell(cell).unwrap();
            for [u,v] in [[tri[0],tri[1]],[tri[1],tri[2]],[tri[2],tri[0]]] { *edges.entry((u.min(v),u.max(v))).or_default() += 1; }
        }
        assert_eq!(edges.values().all(|&count|count==2), cfg!(feature="retained"));
    }
    if case != "line_arrows" {
        let values=output.point_data[0].as_scalar().unwrap();
        for glyph in 0..points {
            let expected=if case=="tensor_glyphs" {4.0} else {(1.0+0.25_f64.powi(2)+0.5_f64.powi(2)).sqrt()};
            assert!(values[glyph*vertices..(glyph+1)*vertices].iter().all(|v|(v-expected).abs()<1e-12));
        }
    }
}

fn main() {
    for points in [128usize,1024,4096] {
        let dataset=DataSet::surface("glyphs", (0..points).map(|i|[i as f64*2.0,0.0,0.0]).collect::<Vec<_>>(), &[])
            .with_field(Field::vector("v",vec![[1.0,0.25,0.5];points]))
            .with_field(Field::tensor("t",vec![[4.0,1.0,1.0,0.0,0.0,0.0];points]));
        for case in ["line_arrows","solid_arrows","tensor_glyphs"] {
            let operation=||match case {
                "line_arrows"=>glyphs(&dataset,"v",1.0,1,GlyphKind::Arrow).unwrap(),
                "solid_arrows"=>solid_arrows(&dataset,"v",1.0,1,0.05).unwrap(),
                _=>tensor_glyphs(&dataset,"t",1.0,1).unwrap(),
            };
            let warm=black_box(operation());check(&warm,points,case);drop(warm);
            let mut times=Vec::with_capacity(5);let mut counts=Vec::with_capacity(5);let mut bytes=Vec::with_capacity(5);
            for _ in 0..5 {
                let mut probe=AllocProbe::new();let start=Instant::now();let output=black_box(operation());let elapsed=start.elapsed().as_nanos();let sample=probe.sample("glyphs");
                times.push(elapsed);counts.push(sample.count);bytes.push(sample.bytes);check(&output,points,case);drop(output);
            }
            println!(r#"{{"points":{points},"case":"{case}","times_ns":{times:?},"allocation_calls":{counts:?},"allocated_bytes":{bytes:?},"allocator_instrumentation":{}}}"#,cfg!(feature="allocations"));
        }
    }
}
